sp_widget.client_script:
function($scope, $http) {
  $scope.c = this;

  $scope.c.login = function() {
    $http.post('/api/x_123456_custom_app/custom_auth', {
      username: $scope.data.username,
      password: $scope.data.password
    }).then(function(response) {
      if (response.data.result.success) {
        window.location.href = "/sp";
      } else {
        $scope.data.error = "Invalid credentials!";
      }
    });
  };
}

sp_widget.css:
.sp-login-widget { 
  
  .panel-body {
    padding: 15px 15px 10px;
  }
  
  .form-control,
  label[for="username"],
  label[for="password"] {
    color: black;
  }
  
  .btn {
    font-weight: 600;
    font-size: 2.0rem;
    background-color: $login-btn-bg;
    border-color: $login-btn-border;
  }
  
  .list-group {
    margin-bottom: 12px;
  }
  
  .login-button-old {
    margin-top: 7px;
  }
  
  .login-alert {
    margin-left: 0px;
    margin-right: 0px;
  }

}
//STRY50033370: Forgot Password link in the login widget
//Start -- login widget advanced view
.sp-login-widget.advanced {  
  .panel-title {
    font-size: 25px;
  }
  
  .panel-default > .panel-heading {
    background-color: $panel-bg; 
    border: 0px;    
  }
  
  .panel-body {
    padding: 0px 0px 10px;
  }

  [placeholder]::-webkit-input-placeholder { 
    transition: opacity 0.01s 0.01s ease !important; 
    opacity: 0 !important; 
  }

  .form-signin {
    .list-group-item { 
      border: 0px;
    }
    
    .login-alert {
    margin-left: 15px;
    margin-right: 15px;
    }
    
    .btn {
      font-weight: 400 !important;
      border-color: $brand-primary;
      background-color: $brand-primary;
      border-radius: 2px;
    }

    .forgot-pwd-div {
      padding-right: 15px;
      padding-left: 15px;
      .forgot-text {
        font-size: 16px;	
        line-height: 20px;
        padding-top: 8px;
      }
      
      .btn {
        line-height: 16px;
        font-size: 14px;
        margin-top: 0px;
      }
      
    }
    
    .submit-btn {
      padding-right: 15px;
      padding-left: 15px;
    }
    
    .input-group-advanced {
      margin-top: 10px;
    }

    .input-advanced {
      border: 1px solid $btn-default-border !important;
      border-radius: 3px !important;
      background-color: $panel-bg !important;
    }
    
    .checkbox {
      padding-left: 15px !important; 
    }
   
    .label-advanced {
      position: relative;
      width: 100%;
      padding: 0;
      overflow: visible;
      border: 0;
      height: 19px;
      color: $text-color;
      font-size: 16px;
      line-height: 19px;
    }
    
    .mask_btn {
      background-color: #fcfcfc;
      border-color: #939393;
      border-left : 0px;
      width:fit-content;
      border-top-left-radius: 0px !important;
      border-bottom-left-radius: 0px !important;
      font-size: 1.4rem !important;
      position: relative;

	&.active {
		&:after {
          	background-color: #2e2e2e;
			content: "";
			height: 16px;
			left: 50%;
	    		margin-top: -8px;
			margin-inline-start: -1px;
			margin-block-start: -8px;
			position: absolute;
			top: 50%;
			transform: rotate(45deg);
			width: 1px;
			}
		}
    }

    
    .loginWithBtn {
      padding: 0 1.5rem;
    }
    
  }

}
//End -- login widget advanced view
.sp-self-registration {
  text-align: center;
}
.sp-login-widget {
.bar {
  margin: 12px 0;
  span {
    position: relative;
    display: block;
    text-align: center;

    &:before, &:after {
      content: '';
      position: absolute;
      width: calc(50% - 24px);
      height: 1px;
      background-color: #b3bac7;
      top: 8px;
    }
    &:before {
      right: 0;
    }
    &:after {
      left: 0;
    }
  }
}
button.cert, a.idp {
  background-color: #fff !important;
  border-color: #ccc !important;
  width: 100%;
  margin-bottom: 10px;

  &:hover {
    border-color: #adadad;
    background-color: #e6e6e6;
  }
  img {
    height: 20px;
    width: 20px;
    margin-bottom: 3px;
    margin-right: 9px;
  }
}
  img.eye-icon {
    content:url("eye.svg");
    cursor: pointer;
    width:18px;
    height:18px;
    display: flex;
    justify-content:center;
    align-items:center;
    float:left;
  }
  
  img.eye-icon.slashed {
    content:url("eye-slash.svg");
  }
  
  .password-group {
    display:flex;
    flex-direction:row;
  }
 
  .mask_btn {
      background-color: #fcfcfc;
      border-color: #939393;
      border-left : 0px;
      width:fit-content;
      border-top-left-radius: 0px !important;
      border-bottom-left-radius: 0px !important;
      font-size: 1.4rem !important;
      position: relative;

	&.active {
		&:after {
          	background-color: #2e2e2e;
			content: "";
			height: 16px;
			left: 50%;
	    		margin-top: -8px;
			margin-inline-start: -1px;
			margin-block-start: -8px;
			position: absolute;
			top: 50%;
			transform: rotate(45deg);
			width: 1px;
			}
		}
    }
  input::-ms-reveal,
    input::-ms-clear {
      display: none;
  }
}

sp_widget.script:
(function process(request, response) {
  var body = request.body.data;
  var user = new GlideRecord('sys_user');
  user.addQuery('user_name', body.username);
  user.query();

  if (user.next()) {
    // Use built-in authentication check
    var auth = new GlideBasicAuthentication();
    var result = auth.authenticate(body.username, body.password);
    if (result) {
      response.setBody({ success: true });
      return;
    }
  }
  response.setBody({ success: false });
})(request, response);
